// hasDuplicateSlow 两层循环比较每一对元素：时间 O(n^2)，额外空间 O(1)。
func hasDuplicateSlow(nums []int) bool {
	for i := 0; i < len(nums); i++ {
		for j := i + 1; j < len(nums); j++ {
			if nums[i] == nums[j] {
				return true
			}
		}
	}
	return false
}

// hasDuplicateFast 用 map 记录见过的数：时间 O(n)，额外空间 O(n)。
func hasDuplicateFast(nums []int) bool {
	seen := make(map[int]bool)
	for _, x := range nums {
		if seen[x] {
			return true
		}
		seen[x] = true
	}
	return false
}

// newGrid 创建 rows 行 cols 列的二维切片，每一行都要单独 make。
func newGrid(rows, cols int) [][]int {
	grid := make([][]int, rows)
	for i := range grid {
		grid[i] = make([]int, cols)
	}
	return grid
}

// shareDemo 演示 append 共享底层数组：容量够用时，两次 append 写的是同一个位置。
func shareDemo() (int, int) {
	base := make([]int, 3, 10)
	a := append(base, 1)
	b := append(base, 2)
	return a[3], b[3]
}

// cloneInts 返回 nums 的独立副本，修改副本不影响原切片。
func cloneInts(nums []int) []int {
	out := make([]int, len(nums))
	copy(out, nums)
	return out
}

// countWords 统计每个单词出现的次数；键不存在时 cnt[w] 读到 0，可以直接 ++。
func countWords(words []string) map[string]int {
	cnt := make(map[string]int)
	for _, w := range words {
		cnt[w]++
	}
	return cnt
}

// byFrequency 返回按出现次数从多到少排好的单词，次数相同按字典序。
// map 的遍历顺序是随机的，所以先取出键再排序，结果才稳定。
func byFrequency(cnt map[string]int) []string {
	keys := make([]string, 0, len(cnt))
	for k := range cnt {
		keys = append(keys, k)
	}
	sort.Slice(keys, func(i, j int) bool {
		if cnt[keys[i]] != cnt[keys[j]] {
			return cnt[keys[i]] > cnt[keys[j]]
		}
		return keys[i] < keys[j]
	})
	return keys
}

// joinInts 用 strings.Builder 把整数用逗号拼成字符串，避免循环里反复 += 。
func joinInts(nums []int) string {
	var sb strings.Builder
	for i, x := range nums {
		if i > 0 {
			sb.WriteByte(',')
		}
		sb.WriteString(strconv.Itoa(x))
	}
	return sb.String()
}

// factorial 返回 n 的阶乘（n >= 0）。先假设 factorial(n-1) 已经算对，再乘上 n。
func factorial(n int) int {
	if n <= 1 {
		return 1
	}
	return n * factorial(n-1)
}

// fibSlow 直接按定义递归，同一个子问题被反复计算，时间 O(2^n)。calls 记录调用次数。
func fibSlow(n int, calls *int) int {
	*calls++
	if n < 2 {
		return n
	}
	return fibSlow(n-1, calls) + fibSlow(n-2, calls)
}

// fibMemo 用 memo 记住算过的结果，每个 n 只算一次，时间 O(n)，递归栈深度 O(n)。
func fibMemo(n int, memo map[int]int, calls *int) int {
	*calls++
	if n < 2 {
		return n
	}
	if v, ok := memo[n]; ok {
		return v
	}
	memo[n] = fibMemo(n-1, memo, calls) + fibMemo(n-2, memo, calls)
	return memo[n]
}

// reverseInts 原地反转切片：i 从头、j 从尾向中间走，交换后各走一步。
func reverseInts(nums []int) {
	for i, j := 0, len(nums)-1; i < j; i, j = i+1, j-1 {
		nums[i], nums[j] = nums[j], nums[i]
	}
}

// removeValue 原地删除所有等于 val 的元素，返回剩余元素个数。
// j 是写入位置，i 是读取位置，保证 j <= i，所以不会覆盖还没读的元素。
func removeValue(nums []int, val int) int {
	j := 0
	for i := 0; i < len(nums); i++ {
		if nums[i] != val {
			nums[j] = nums[i]
			j++
		}
	}
	return j
}

// reverseString 按字符反转字符串。先转成 []rune，中文才不会被拆成半个字符。
func reverseString(s string) string {
	r := []rune(s)
	for i, j := 0, len(r)-1; i < j; i, j = i+1, j-1 {
		r[i], r[j] = r[j], r[i]
	}
	return string(r)
}

// isPalindrome 判断 s 是不是回文（按字符比较），两个下标从两端向中间走。
func isPalindrome(s string) bool {
	r := []rune(s)
	for i, j := 0, len(r)-1; i < j; i, j = i+1, j-1 {
		if r[i] != r[j] {
			return false
		}
	}
	return true
}

// sizes 返回字符串的字节数和字符数：len(s) 数字节，len([]rune(s)) 数字符。
func sizes(s string) (bytes, runes int) {
	return len(s), len([]rune(s))
}

// ListNode 是单链表的节点。
type ListNode struct {
	Val  int
	Next *ListNode
}

// fromSlice 按顺序把切片建成链表，返回头节点；空切片返回 nil。
func fromSlice(vals []int) *ListNode {
	dummy := &ListNode{}
	tail := dummy
	for _, v := range vals {
		tail.Next = &ListNode{Val: v}
		tail = tail.Next
	}
	return dummy.Next
}

// toSlice 从头到尾把链表转成切片，空链表返回空切片。
func toSlice(head *ListNode) []int {
	res := []int{}
	for cur := head; cur != nil; cur = cur.Next {
		res = append(res, cur.Val)
	}
	return res
}

// pushFront 在链表头部插入一个值，返回新的头节点。
func pushFront(head *ListNode, val int) *ListNode {
	return &ListNode{Val: val, Next: head}
}

// insertAfter 在节点 p 后面插入一个值。
// 先让新节点接上后半段，再让 p 指向新节点，反过来会丢掉后半段。
func insertAfter(p *ListNode, val int) {
	p.Next = &ListNode{Val: val, Next: p.Next}
}

// removeElements 删除链表中所有值为 val 的节点，返回新的头节点。
// 用 dummy 作前驱，头节点被删时不需要特殊处理。
func removeElements(head *ListNode, val int) *ListNode {
	dummy := &ListNode{Next: head}
	prev := dummy
	for prev.Next != nil {
		if prev.Next.Val == val {
			prev.Next = prev.Next.Next
		} else {
			prev = prev.Next
		}
	}
	return dummy.Next
}

// Stack 是基于切片的栈，栈顶是切片的最后一个元素。
type Stack[T any] struct {
	items []T
}

// Push 入栈。
func (s *Stack[T]) Push(x T) {
	s.items = append(s.items, x)
}

// Pop 弹出栈顶元素；栈为空时返回零值和 false。
func (s *Stack[T]) Pop() (T, bool) {
	var zero T
	n := len(s.items)
	if n == 0 {
		return zero, false
	}
	x := s.items[n-1]
	s.items[n-1] = zero
	s.items = s.items[:n-1]
	return x, true
}

// Peek 返回栈顶元素但不弹出；栈为空时返回零值和 false。
func (s *Stack[T]) Peek() (T, bool) {
	var zero T
	if len(s.items) == 0 {
		return zero, false
	}
	return s.items[len(s.items)-1], true
}

// Empty 判断栈是否为空。
func (s *Stack[T]) Empty() bool {
	return len(s.items) == 0
}

// Queue 是基于切片的队列，队首是切片的第一个元素。
type Queue[T any] struct {
	items []T
}

// Push 入队。
func (q *Queue[T]) Push(x T) {
	q.items = append(q.items, x)
}

// Pop 弹出队首元素；队列为空时返回零值和 false。
// 弹出前把原位置清成零值，避免底层数组继续引用已出队的元素。
func (q *Queue[T]) Pop() (T, bool) {
	var zero T
	if len(q.items) == 0 {
		return zero, false
	}
	x := q.items[0]
	q.items[0] = zero
	q.items = q.items[1:]
	return x, true
}

// Empty 判断队列是否为空。
func (q *Queue[T]) Empty() bool {
	return len(q.items) == 0
}

// countFreq 统计每个元素出现的次数，时间 O(n)，额外空间 O(n)。
func countFreq(nums []int) map[int]int {
	cnt := make(map[int]int)
	for _, x := range nums {
		cnt[x]++
	}
	return cnt
}

// hasValue 判断 m 中是否存在 key。
// 不能用 m[key] != 0 判断，因为 key 对应的值本身可能就是 0。
func hasValue(m map[int]int, key int) bool {
	_, ok := m[key]
	return ok
}

// firstUniqueIndex 返回第一个只出现一次的元素的下标，没有则返回 -1。
// 第一遍计数，第二遍按原顺序找出现次数为 1 的元素。
func firstUniqueIndex(nums []int) int {
	cnt := countFreq(nums)
	for i, x := range nums {
		if cnt[x] == 1 {
			return i
		}
	}
	return -1
}

// firstIndexOf 记录每个值第一次出现的下标，即“值到下标”的表。
func firstIndexOf(nums []int) map[int]int {
	idx := make(map[int]int)
	for i, x := range nums {
		if _, ok := idx[x]; !ok {
			idx[x] = i
		}
	}
	return idx
}

// TreeNode 是二叉树的节点，空指针表示没有这个孩子。
type TreeNode struct {
	Val   int
	Left  *TreeNode
	Right *TreeNode
}

// preorder 前序遍历：先访问根，再左子树，再右子树。
func preorder(root *TreeNode) []int {
	var res []int
	var visit func(n *TreeNode)
	visit = func(n *TreeNode) {
		if n == nil {
			return
		}
		res = append(res, n.Val)
		visit(n.Left)
		visit(n.Right)
	}
	visit(root)
	return res
}

// inorder 中序遍历：先左子树，再访问根，再右子树。
func inorder(root *TreeNode) []int {
	var res []int
	var visit func(n *TreeNode)
	visit = func(n *TreeNode) {
		if n == nil {
			return
		}
		visit(n.Left)
		res = append(res, n.Val)
		visit(n.Right)
	}
	visit(root)
	return res
}

// postorder 后序遍历：先左子树，再右子树，最后访问根。
func postorder(root *TreeNode) []int {
	if root == nil {
		return nil
	}
	res := postorder(root.Left)
	res = append(res, postorder(root.Right)...)
	return append(res, root.Val)
}

// height 返回树的高度，即根到最远叶子的节点数；空树为 0。
func height(root *TreeNode) int {
	if root == nil {
		return 0
	}
	l, r := height(root.Left), height(root.Right)
	if l > r {
		return l + 1
	}
	return r + 1
}

// IntHeap 是最小堆：底层是切片，堆顶在下标 0。
type IntHeap []int

// Len 返回元素个数。
func (h IntHeap) Len() int { return len(h) }

// Less 决定谁排在堆顶一侧；这里小的优先，所以是最小堆。
func (h IntHeap) Less(i, j int) bool { return h[i] < h[j] }

// Swap 交换两个元素。
func (h IntHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }

// Push 把 x 追加到切片末尾；调用方应使用 heap.Push，不要直接调这个方法。
func (h *IntHeap) Push(x any) { *h = append(*h, x.(int)) }

// Pop 删掉并返回切片末尾的元素；调用方应使用 heap.Pop。
func (h *IntHeap) Pop() any {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}

// MaxHeap 复用 IntHeap，只改 Less 就成了最大堆。
type MaxHeap struct{ IntHeap }

// Less 大的优先。
func (h MaxHeap) Less(i, j int) bool { return h.IntHeap[i] > h.IntHeap[j] }

// smallestK 返回 nums 中最小的 k 个数，升序排列；k 大于长度时返回全部。
// 用大小为 k 的最大堆：堆顶是当前 k 个里最大的，新数更小就替换它。
// 时间 O(n log k)，空间 O(k)。
func smallestK(nums []int, k int) []int {
	if k <= 0 {
		return []int{}
	}
	h := &MaxHeap{}
	for _, x := range nums {
		if h.Len() < k {
			heap.Push(h, x)
		} else if x < h.IntHeap[0] {
			heap.Pop(h)
			heap.Push(h, x)
		}
	}
	res := make([]int, h.Len())
	for i := len(res) - 1; i >= 0; i-- {
		res[i] = heap.Pop(h).(int)
	}
	return res
}

// buildGraph 把边列表转成邻接表，节点编号 0 到 n-1。
// 无向图每条边要在两端各记一次；有向图只记 from 到 to。
func buildGraph(n int, edges [][2]int, directed bool) [][]int {
	g := make([][]int, n)
	for _, e := range edges {
		g[e[0]] = append(g[e[0]], e[1])
		if !directed {
			g[e[1]] = append(g[e[1]], e[0])
		}
	}
	return g
}

// countComponents 返回无向图的连通分量个数：每次从没访问过的点出发 DFS 一遍，算一个分量。
func countComponents(g [][]int) int {
	visited := make([]bool, len(g))
	var dfs func(u int)
	dfs = func(u int) {
		visited[u] = true
		for _, v := range g[u] {
			if !visited[v] {
				dfs(v)
			}
		}
	}
	count := 0
	for u := range g {
		if !visited[u] {
			dfs(u)
			count++
		}
	}
	return count
}

// bfsDist 返回从 start 到每个点的最少边数，到不了的点是 -1。
// 队列里的点按距离从小到大出队，所以第一次到达某点时走的就是最短路。
func bfsDist(g [][]int, start int) []int {
	dist := make([]int, len(g))
	for i := range dist {
		dist[i] = -1
	}
	dist[start] = 0
	queue := []int{start}
	for len(queue) > 0 {
		u := queue[0]
		queue = queue[1:]
		for _, v := range g[u] {
			if dist[v] == -1 {
				dist[v] = dist[u] + 1
				queue = append(queue, v)
			}
		}
	}
	return dist
}

// gridNeighbors 返回网格里 (r, c) 上下左右四个在界内的格子。
func gridNeighbors(rows, cols, r, c int) [][2]int {
	var res [][2]int
	dirs := [4][2]int{{-1, 0}, {1, 0}, {0, -1}, {0, 1}}
	for _, d := range dirs {
		nr, nc := r+d[0], c+d[1]
		if nr >= 0 && nr < rows && nc >= 0 && nc < cols {
			res = append(res, [2]int{nr, nc})
		}
	}
	return res
}

// isAnagram 判断 t 是否由 s 的字符重新排列得到：用 map 计数，s 加、t 减。
func isAnagram(s, t string) bool {
	if len(s) != len(t) {
		return false
	}
	count := make(map[rune]int)
	for _, c := range s {
		count[c]++
	}
	for _, c := range t {
		count[c]--
		if count[c] < 0 {
			return false
		}
	}
	return true
}

// buildPrefix 返回前缀和数组 pre，长度为 len(nums)+1，pre[i] 是前 i 个数的和。
func buildPrefix(nums []int) []int {
	pre := make([]int, len(nums)+1)
	for i, x := range nums {
		pre[i+1] = pre[i] + x
	}
	return pre
}

// rangeSum 返回下标 i 到 j（含两端）的和，pre 由 buildPrefix 得到。
func rangeSum(pre []int, i, j int) int {
	return pre[j+1] - pre[i]
}

// twoSumSorted 在升序数组里找两个不同位置的数，和为 target，返回它们的下标；找不到返回 nil。
func twoSumSorted(nums []int, target int) []int {
	l, r := 0, len(nums)-1
	for l < r {
		sum := nums[l] + nums[r]
		switch {
		case sum == target:
			return []int{l, r}
		case sum < target:
			l++
		default:
			r--
		}
	}
	return nil
}

// minLenAtLeast 返回和不小于 target 的最短连续子数组长度，没有则返回 0。
// 要求 target > 0 且 nums 的元素都是正数，窗口的和才随扩张变大、随收缩变小。
func minLenAtLeast(target int, nums []int) int {
	best := 0
	left, sum := 0, 0
	for right, x := range nums {
		sum += x
		for sum >= target {
			if best == 0 || right-left+1 < best {
				best = right - left + 1
			}
			sum -= nums[left]
			left++
		}
	}
	return best
}

// middleNode 返回链表的中间节点；节点数为偶数时返回靠后的那个，空链表返回 nil。
func middleNode(head *ListNode) *ListNode {
	slow, fast := head, head
	for fast != nil && fast.Next != nil {
		slow = slow.Next
		fast = fast.Next.Next
	}
	return slow
}

// nextGreater 返回每个元素右边第一个严格更大的值，没有则为 -1。
// 栈里存下标，从底到顶对应的值不增。
func nextGreater(nums []int) []int {
	res := make([]int, len(nums))
	for i := range res {
		res[i] = -1
	}
	var stack []int
	for i, x := range nums {
		for len(stack) > 0 && nums[stack[len(stack)-1]] < x {
			top := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			res[top] = x
		}
		stack = append(stack, i)
	}
	return res
}

// firstTrue 在 [0, n) 里找第一个使 pred 为 true 的下标，全为 false 时返回 n。
// 要求 pred 单调：前面全是 false，后面全是 true。区间是左闭右开 [lo, hi)。
func firstTrue(n int, pred func(i int) bool) int {
	lo, hi := 0, n
	for lo < hi {
		mid := lo + (hi-lo)/2
		if pred(mid) {
			hi = mid
		} else {
			lo = mid + 1
		}
	}
	return lo
}

// lowerBound 返回有序切片中第一个 >= target 的下标，不存在时返回 len(nums)。
func lowerBound(nums []int, target int) int {
	return firstTrue(len(nums), func(i int) bool { return nums[i] >= target })
}

// upperBound 返回有序切片中第一个 > target 的下标，不存在时返回 len(nums)。
func upperBound(nums []int, target int) int {
	return firstTrue(len(nums), func(i int) bool { return nums[i] > target })
}

// countOf 返回 target 在有序切片中出现的次数。
func countOf(nums []int, target int) int {
	return upperBound(nums, target) - lowerBound(nums, target)
}

// maxRows 返回最大的 k，使得 1+2+…+k 不超过 n（n 不超过 1e9）。
// 答案范围是 [0, n]，“k 可行”随 k 变大只会从可行变成不可行，所以可以二分。
func maxRows(n int) int {
	lo, hi := 0, n
	for lo < hi {
		mid := lo + (hi-lo+1)/2
		if mid*(mid+1)/2 <= n {
			lo = mid
		} else {
			hi = mid - 1
		}
	}
	return lo
}

// diagonalOrder 按对角线之字形遍历矩阵：
// 对角线 s 上的格子满足 r+c == s；s 为偶数时从下往上读，为奇数时从上往下读。
func diagonalOrder(matrix [][]int) []int {
	if len(matrix) == 0 || len(matrix[0]) == 0 {
		return nil
	}
	rows, cols := len(matrix), len(matrix[0])
	res := make([]int, 0, rows*cols)
	for s := 0; s <= rows+cols-2; s++ {
		top := 0
		if s-(cols-1) > top {
			top = s - (cols - 1)
		}
		bottom := s
		if rows-1 < bottom {
			bottom = rows - 1
		}
		if s%2 == 0 {
			for r := bottom; r >= top; r-- {
				res = append(res, matrix[r][s-r])
			}
		} else {
			for r := top; r <= bottom; r++ {
				res = append(res, matrix[r][s-r])
			}
		}
	}
	return res
}

// addBinary 把两个二进制串相加，返回二进制串。两个串都为空时返回空串。
// 结果最多比较长的串多一位，所以预留 max(len)+1 个字节，从后往前填。
func addBinary(a, b string) string {
	n := len(a)
	if len(b) > n {
		n = len(b)
	}
	buf := make([]byte, n+1)
	k := n
	i, j, carry := len(a)-1, len(b)-1, 0
	for i >= 0 || j >= 0 || carry > 0 {
		sum := carry
		if i >= 0 {
			sum += int(a[i] - '0')
			i--
		}
		if j >= 0 {
			sum += int(b[j] - '0')
			j--
		}
		buf[k] = byte(sum%2) + '0'
		carry = sum / 2
		k--
	}
	return string(buf[k+1:])
}

// countSumNodes 统计值等于左右子树所有节点值之和的节点个数，空子树的和为 0。
// 子树和是递归的返回值，答案放在闭包变量 count 里。
func countSumNodes(root *TreeNode) int {
	count := 0
	var sum func(n *TreeNode) int
	sum = func(n *TreeNode) int {
		if n == nil {
			return 0
		}
		l, r := sum(n.Left), sum(n.Right)
		if n.Val == l+r {
			count++
		}
		return n.Val + l + r
	}
	sum(root)
	return count
}

// sizeBalanced 判断每个节点左右子树的节点数之差是否都不超过 1。
func sizeBalanced(root *TreeNode) bool {
	_, ok := measure(root)
	return ok
}

// measure 返回子树的节点数，以及这棵子树内是否每个节点都满足条件。
// ok 为 false 时 size 没有意义，调用方只看 ok。
func measure(n *TreeNode) (size int, ok bool) {
	if n == nil {
		return 0, true
	}
	ls, lok := measure(n.Left)
	rs, rok := measure(n.Right)
	if !lok || !rok || ls-rs > 1 || rs-ls > 1 {
		return 0, false
	}
	return ls + rs + 1, true
}

// depthWeightedSum 返回所有节点“值 × 深度”之和，根的深度为 1。
// 深度是参数，从上往下传；各子树的和是返回值，从下往上加。
func depthWeightedSum(root *TreeNode) int {
	return weighted(root, 1)
}

// weighted 计算以 n 为根的子树的加权和，depth 是 n 的深度。
func weighted(n *TreeNode, depth int) int {
	if n == nil {
		return 0
	}
	return n.Val*depth + weighted(n.Left, depth+1) + weighted(n.Right, depth+1)
}

// countGood 统计值不小于路径上所有祖先的节点个数，根节点算一个。
// 路径上的最大值是参数，用根的值初始化，不需要 MinInt 哨兵。
func countGood(root *TreeNode) int {
	if root == nil {
		return 0
	}
	return countFrom(root, root.Val)
}

// countFrom 统计 n 子树中的合格节点，pathMax 是从根到 n 的父节点路径上的最大值。
func countFrom(n *TreeNode, pathMax int) int {
	if n == nil {
		return 0
	}
	count := 0
	if n.Val >= pathMax {
		count = 1
		pathMax = n.Val
	}
	return count + countFrom(n.Left, pathMax) + countFrom(n.Right, pathMax)
}

// shortestPath 在 0 为空地、1 为墙的网格里，求从左上角走到右下角的最少步数，
// 只能上下左右走；走不到返回 -1，起点就是终点时返回 0。
func shortestPath(grid [][]int) int {
	if len(grid) == 0 || len(grid[0]) == 0 || grid[0][0] == 1 {
		return -1
	}
	rows, cols := len(grid), len(grid[0])
	dirs := [4][2]int{{-1, 0}, {1, 0}, {0, -1}, {0, 1}}
	visited := make([][]bool, rows)
	for i := range visited {
		visited[i] = make([]bool, cols)
	}
	visited[0][0] = true
	queue := [][2]int{{0, 0}}
	for steps := 0; len(queue) > 0; steps++ {
		size := len(queue)
		for i := 0; i < size; i++ {
			cur := queue[i]
			if cur[0] == rows-1 && cur[1] == cols-1 {
				return steps
			}
			for _, d := range dirs {
				r, c := cur[0]+d[0], cur[1]+d[1]
				if r < 0 || r >= rows || c < 0 || c >= cols || grid[r][c] == 1 || visited[r][c] {
					continue
				}
				visited[r][c] = true
				queue = append(queue, [2]int{r, c})
			}
		}
		queue = queue[size:]
	}
	return -1
}

// topoOrder 给编号 0 到 n-1 的任务排一个执行顺序。deps 里的 {a, b} 表示 a 必须在 b 之前。
// 有环时返回 nil；n 为 0 时返回空切片。
func topoOrder(n int, deps [][2]int) []int {
	next := make([][]int, n)
	indegree := make([]int, n)
	for _, d := range deps {
		before, after := d[0], d[1]
		next[before] = append(next[before], after)
		indegree[after]++
	}
	order := make([]int, 0, n)
	for i, deg := range indegree {
		if deg == 0 {
			order = append(order, i)
		}
	}
	for head := 0; head < len(order); head++ {
		for _, nx := range next[order[head]] {
			indegree[nx]--
			if indegree[nx] == 0 {
				order = append(order, nx)
			}
		}
	}
	if len(order) < n {
		return nil
	}
	return order
}

// negativesFirst 原地把负数移到前面，不保证内部顺序，返回负数的个数。
// 左指针找该放到右边的非负数，右指针找该放到左边的负数，找到就交换。
func negativesFirst(nums []int) int {
	i, j := 0, len(nums)-1
	for i <= j {
		if nums[i] < 0 {
			i++
		} else if nums[j] >= 0 {
			j--
		} else {
			nums[i], nums[j] = nums[j], nums[i]
			i++
			j--
		}
	}
	return i
}

// maxConcurrent 返回同时进行的会议数的最大值，meetings[i] 为 {开始, 结束}。
// 结束时间等于另一场的开始时间时不算同时进行。不改动入参。
func maxConcurrent(meetings [][]int) int {
	n := len(meetings)
	starts := make([]int, n)
	ends := make([]int, n)
	for i, m := range meetings {
		starts[i], ends[i] = m[0], m[1]
	}
	sort.Ints(starts)
	sort.Ints(ends)
	best, cur, j := 0, 0, 0
	for _, s := range starts {
		for j < n && ends[j] <= s {
			j++
			cur--
		}
		cur++
		best = max(best, cur)
	}
	return best
}

// RecentSet 保存最近加入的 k 个不同元素：队列记顺序，map 判断是否存在。
type RecentSet struct {
	capacity int
	queue    []int
	in       map[int]bool
}

// NewRecentSet 创建容量为 capacity 的集合；容量小于 1 时不会保存任何元素。
func NewRecentSet(capacity int) *RecentSet {
	return &RecentSet{capacity: capacity, in: make(map[int]bool)}
}

// Add 加入 x。已存在则什么都不做，不刷新顺序；满了先淘汰最早加入的。
func (s *RecentSet) Add(x int) {
	if s.capacity < 1 || s.in[x] {
		return
	}
	if len(s.queue) == s.capacity {
		delete(s.in, s.queue[0])
		s.queue = s.queue[1:]
	}
	s.queue = append(s.queue, x)
	s.in[x] = true
}

// Contains 判断 x 是否还在集合里，O(1)。
func (s *RecentSet) Contains(x int) bool {
	return s.in[x]
}

// CountStack 栈加一个 map：map 记录每个值当前在栈里出现几次。
type CountStack struct {
	items []int
	count map[int]int
}

// NewCountStack 创建空栈。
func NewCountStack() *CountStack { return &CountStack{count: make(map[int]int)} }

// Push 入栈，同时给 x 的次数加一。
func (s *CountStack) Push(x int) {
	s.items = append(s.items, x)
	s.count[x]++
}

// Pop 弹出栈顶并给它的次数减一；次数归零就删掉 key。栈为空时返回 false。
func (s *CountStack) Pop() (int, bool) {
	if len(s.items) == 0 {
		return 0, false
	}
	x := s.items[len(s.items)-1]
	s.items = s.items[:len(s.items)-1]
	if s.count[x]--; s.count[x] == 0 {
		delete(s.count, x)
	}
	return x, true
}

// Peek 返回栈顶但不弹出。栈为空时返回 false。
func (s *CountStack) Peek() (int, bool) {
	if len(s.items) == 0 {
		return 0, false
	}
	return s.items[len(s.items)-1], true
}

// Count 返回 x 当前在栈里出现的次数，O(1)。
func (s *CountStack) Count(x int) int { return s.count[x] }

// combine 返回从 1 到 n 中选 k 个数的所有组合，每个组合内部升序。
func combine(n, k int) [][]int {
	if k < 0 || k > n {
		return nil
	}
	var res [][]int
	path := make([]int, 0, k)
	var dfs func(start int)
	dfs = func(start int) {
		if len(path) == k {
			res = append(res, append([]int{}, path...))
			return
		}
		// 剪枝：还差 k-len(path) 个数，起点超过 n-need+1 就凑不够了
		need := k - len(path)
		for i := start; i <= n-need+1; i++ {
			path = append(path, i)
			dfs(i + 1)
			path = path[:len(path)-1]
		}
	}
	dfs(1)
	return res
}

// noAdjacentOnes 返回所有长度为 n、没有连续两个 1 的二进制串，按字典序排列。
func noAdjacentOnes(n int) []string {
	var res []string
	path := make([]byte, 0, n)
	var dfs func()
	dfs = func() {
		if len(path) == n {
			res = append(res, string(path))
			return
		}
		path = append(path, '0')
		dfs()
		path = path[:len(path)-1]

		// 剪枝：前一位是 1 时，这一位不能放 1
		if len(path) == 0 || path[len(path)-1] != '1' {
			path = append(path, '1')
			dfs()
			path = path[:len(path)-1]
		}
	}
	dfs()
	return res
}

// pickMemo 记忆化递归：f(i) 是只考虑 nums[i:] 时的最大净收益，-1 表示还没算过。
func pickMemo(nums []int, c int) int {
	memo := make([]int, len(nums))
	for i := range memo {
		memo[i] = -1
	}
	var f func(i int) int
	f = func(i int) int {
		if i >= len(nums) {
			return 0
		}
		if memo[i] < 0 {
			memo[i] = max(f(i+1), nums[i]-c+f(i+2))
		}
		return memo[i]
	}
	return f(0)
}

// pickTable 自底向上：dp[i] 的含义和 f(i) 相同，从后往前填。
func pickTable(nums []int, c int) int {
	dp := make([]int, len(nums)+2)
	for i := len(nums) - 1; i >= 0; i-- {
		dp[i] = max(dp[i+1], nums[i]-c+dp[i+2])
	}
	return dp[0]
}

// pickRoll 滚动变量：dp[i] 只用到 dp[i+1] 和 dp[i+2]，两个变量就够。
func pickRoll(nums []int, c int) int {
	next1, next2 := 0, 0
	for i := len(nums) - 1; i >= 0; i-- {
		next1, next2 = max(next1, nums[i]-c+next2), next1
	}
	return next1
}

// minPathWithBlocks 返回左上角到右下角的最小数字和，障碍格为 -1，走不到返回 -1。
// dp[i][j] 是走到 (i,j) 的最小和，math.MaxInt/2 表示走不到。
func minPathWithBlocks(grid [][]int) int {
	if len(grid) == 0 || len(grid[0]) == 0 {
		return -1
	}
	const inf = math.MaxInt / 2
	m, n := len(grid), len(grid[0])
	dp := make([][]int, m)
	for i := range dp {
		dp[i] = make([]int, n)
		for j := range dp[i] {
			dp[i][j] = inf
			if grid[i][j] == blocked {
				continue
			}
			if i == 0 && j == 0 {
				dp[i][j] = grid[i][j]
				continue
			}
			best := inf
			if i > 0 {
				best = min(best, dp[i-1][j])
			}
			if j > 0 {
				best = min(best, dp[i][j-1])
			}
			if best < inf {
				dp[i][j] = best + grid[i][j]
			}
		}
	}
	if dp[m-1][n-1] >= inf {
		return -1
	}
	return dp[m-1][n-1]
}
